Signed-off-by: Rodrigo Vivi <rodrigo.vivi@intel.com>

Here is the root cause:
During remap operations with the skip_prev/skip_next optimization, the code in xe_vma_op_commit set the prev/next pointers to NULL after marking them as skipped. This lost the references to the VMA ends that were not actually unbound. Later, on the unwind path (e.g., due to an error), the original VMA (which had been shrunk by adjusting its range) was re-inserted, but the ends were never removed from the VM, causing an overlapping VMA insertion and triggering a warning. Additionally, the original VMA range was not restored to its full size before re-insertion, exacerbating the overlap.

Here is the patch:

 static int xe_vma_op_commit(struct xe_vm *vm, struct xe_vma_op *op)
 {
 	int err = 0;

 	lockdep_assert_held_write(&vm->lock);

 	switch (op->base.op) {
 	case DRM_GPUVA_OP_MAP:
 		err |= xe_vm_insert_vma(vm, op->map.vma);
 		if (!err)
 			op->flags |= XE_VMA_OP_COMMITTED;
 		break;
 	case DRM_GPUVA_OP_REMAP:
 	{
 		u8 tile_present =
 			gpuva_to_vma(op->base.remap.unmap->va)->tile_present;

 		prep_vma_destroy(vm, gpuva_to_vma(op->base.remap.unmap->va),
 				 true);
 		op->flags |= XE_VMA_OP_COMMITTED;

 		if (op->remap.prev) {
 			err |= xe_vm_insert_vma(vm, op->remap.prev);
 			if (!err)
 				op->flags |= XE_VMA_OP_PREV_COMMITTED;
 			if (!err && op->remap.skip_prev) {
 				op->remap.prev->tile_present =
 					tile_present;
-				op->remap.prev = NULL;
 			}
 		}
 		if (op->remap.next) {
 			err |= xe_vm_insert_vma(vm, op->remap.next);
 			if (!err)
 				op->flags |= XE_VMA_OP_NEXT_COMMITTED;
 			if (!err && op->remap.skip_next) {
 				op->remap.next->tile_present =
 					tile_present;
-				op->remap.next = NULL;
 			}
 		}

-		/* Adjust for partial unbind after removing VMA from VM */
+		/*
+		 * Adjust for partial unbind after removing VMA from VM. In case
+		 * of unwind we might need to undo this later.
+		 */
 		if (!err) {
 			op->base.remap.unmap->va->va.addr = op->remap.start;
 			op->base.remap.unmap->va->va.range = op->remap.range;
 		}
 		break;
 	}
 	case DRM_GPUVA_OP_UNMAP:
 		prep_vma_destroy(vm, gpuva_to_vma(op->base.unmap.va), true);
 		op->flags |= XE_VMA_OP_COMMITTED;
 		break;
 	case DRM_GPUVA_OP_PREFETCH:
 		op->flags |= XE_VMA_OP_COMMITTED;
 		break;
 	default:
 		drm_warn(&vm->xe->drm, "NOT POSSIBLE\n");
 	}

 	return err;
 }


 static int vm_bind_ioctl_ops_parse(struct xe_vm *vm, struct drm_gpuva_ops *ops,
 				   struct xe_vma_ops *vops)
 {
 	struct xe_device *xe = vm->xe;
 	struct drm_gpuva_op *__op;
 	struct xe_tile *tile;
 	u8 id, tile_mask = 0;
 	int err = 0;

 	lockdep_assert_held_write(&vm->lock);

 	for_each_tile(tile, vm->xe, id)
 		tile_mask |= 0x1 << id;

 	drm_gpuva_for_each_op(__op, ops) {
 		struct xe_vma_op *op = gpuva_op_to_vma_op(__op);
 		struct xe_vma *vma;
 		unsigned int flags = 0;

 		INIT_LIST_HEAD(&op->link);
 		list_add_tail(&op->link, &vops->list);
 		op->tile_mask = tile_mask;

 		switch (op->base.op) {
 		case DRM_GPUVA_OP_MAP:
 		{
 			struct xe_vma_mem_attr default_attr = {
 				.preferred_loc = {
 					.devmem_fd = DRM_XE_PREFERRED_LOC_DEFAULT_DEVICE,
 					.migration_policy = DRM_XE_MIGRATE_ALL_PAGES,
 				},
 				.atomic_access = DRM_XE_ATOMIC_UNDEFINED,
 				.default_pat_index = op->map.pat_index,
 				.pat_index = op->map.pat_index,
 			};

 			flags |= op->map.vma_flags & XE_VMA_CREATE_MASK;

 			vma = new_vma(vm, &op->base.map, &default_attr,
 				      flags);
 			if (IS_ERR(vma))
 				return PTR_ERR(vma);

 			op->map.vma = vma;
 			if (((op->map.immediate || !xe_vm_in_fault_mode(vm)) &&
 			     !(op->map.vma_flags & XE_VMA_SYSTEM_ALLOCATOR)) ||
 			    op->map.invalidate_on_bind)
 				xe_vma_ops_incr_pt_update_ops(vops,
 							      op->tile_mask, 1);
 			break;
 		}
 		case DRM_GPUVA_OP_REMAP:
 		{
 			struct xe_vma *old =
 				gpuva_to_vma(op->base.remap.unmap->va);
 			bool skip = xe_vma_is_cpu_addr_mirror(old);
 			u64 start = xe_vma_start(old), end = xe_vma_end(old);
 			int num_remap_ops = 0;

 			if (op->base.remap.prev)
 				start = op->base.remap.prev->va.addr +
 					op->base.remap.prev->va.range;
 			if (op->base.remap.next)
 				end = op->base.remap.next->va.addr;

 			if (xe_vma_is_cpu_addr_mirror(old) &&
 			    xe_svm_has_mapping(vm, start, end)) {
 				if (vops->flags & XE_VMA_OPS_FLAG_MADVISE)
 					xe_svm_unmap_address_range(vm, start, end);
 				else
 					return -EBUSY;
 			}

 			op->remap.start = xe_vma_start(old);
 			op->remap.range = xe_vma_size(old);
+			op->remap.old_start = op->remap.start;
+			op->remap.old_range = op->remap.range;

 			flags |= op->base.remap.unmap->va->flags & XE_VMA_CREATE_MASK;
 			if (op->base.remap.prev) {
 				vma = new_vma(vm, op->base.remap.prev,
 					      &old->attr, flags);
 				if (IS_ERR(vma))
 					return PTR_ERR(vma);

 				op->remap.prev = vma;

 				/*
 				 * Userptr creates a new SG mapping so
 				 * we must also rebind.
 				 */
 				op->remap.skip_prev = skip ||
 					(!xe_vma_is_userptr(old) &&
 					IS_ALIGNED(xe_vma_end(vma),
 						   xe_vma_max_pte_size(old)));
 				if (op->remap.skip_prev) {
 					xe_vma_set_pte_size(vma, xe_vma_max_pte_size(old));
 					op->remap.range -=
 						xe_vma_end(vma) -
 						xe_vma_start(old);
 					op->remap.start = xe_vma_end(vma);
 					vm_dbg(&xe->drm, "REMAP:SKIP_PREV: addr=0x%016llx, range=0x%016llx",
 					       (ULL)op->remap.start,
 					       (ULL)op->remap.range);
 				} else {
 					num_remap_ops++;
 				}
 			}

 			if (op->base.remap.next) {
 				vma = new_vma(vm, op->base.remap.next,
 					      &old->attr, flags);
 				if (IS_ERR(vma))
 					return PTR_ERR(vma);

 				op->remap.next = vma;

 				/*
 				 * Userptr creates a new SG mapping so
 				 * we must also rebind.
 				 */
 				op->remap.skip_next = skip ||
 					(!xe_vma_is_userptr(old) &&
 					IS_ALIGNED(xe_vma_start(vma),
 						   xe_vma_max_pte_size(old)));
 				if (op->remap.skip_next) {
 					xe_vma_set_pte_size(vma, xe_vma_max_pte_size(old));
 					op->remap.range -=
 						xe_vma_end(old) -
 						xe_vma_start(vma);
 					vm_dbg(&xe->drm, "REMAP:SKIP_NEXT: addr=0x%016llx, range=0x%016llx",
 					       (ULL)op->remap.start,
 					       (ULL)op->remap.range);
 				} else {
 					num_remap_ops++;
 				}
 			}
 			if (!skip)
 				num_remap_ops++;

 			xe_vma_ops_incr_pt_update_ops(vops, op->tile_mask, num_remap_ops);
 			break;
 		}
 		case DRM_GPUVA_OP_UNMAP:
 			vma = gpuva_to_vma(op->base.unmap.va);

 			if (xe_vma_is_cpu_addr_mirror(vma) &&
 			    xe_svm_has_mapping(vm, xe_vma_start(vma),
 					       xe_vma_end(vma)) &&
 			    !(vops->flags & XE_VMA_OPS_FLAG_ALLOW_SVM_UNMAP))
 				return -EBUSY;

 			if (!xe_vma_is_cpu_addr_mirror(vma))
 				xe_vma_ops_incr_pt_update_ops(vops, op->tile_mask, 1);
 			break;
 		case DRM_GPUVA_OP_PREFETCH:
 			vma = gpuva_to_vma(op->base.prefetch.va);

 			if (xe_vma_is_userptr(vma)) {
 				err = xe_vma_userptr_pin_pages(to_userptr_vma(vma));
 				if (err)
 					return err;
 			}

 			if (xe_vma_is_cpu_addr_mirror(vma))
 				xe_vma_ops_incr_pt_update_ops(vops, op->tile_mask,
 							      op->prefetch_range.ranges_count);
 			else
 				xe_vma_ops_incr_pt_update_ops(vops, op->tile_mask, 1);

 			break;
 		default:
 			drm_warn(&vm->xe->drm, "NOT POSSIBLE\n");
 		}

 		err = xe_vma_op_commit(vm, op);
 		if (err)
 			return err;
 	}

 	return 0;
 }

 static void xe_vma_op_unwind(struct xe_vm *vm, struct xe_vma_op *op,
 			     bool post_commit, bool prev_post_commit,
 			     bool next_post_commit)
 {
 	lockdep_assert_held_write(&vm->lock);

 	switch (op->base.op) {
 	case DRM_GPUVA_OP_MAP:
 		if (op->map.vma) {
 			prep_vma_destroy(vm, op->map.vma, post_commit);
 			xe_vma_destroy_unlocked(op->map.vma);
 		}
 		break;
 	case DRM_GPUVA_OP_UNMAP:
 	{
 		struct xe_vma *vma = gpuva_to_vma(op->base.unmap.va);

 		if (vma) {
 			xe_svm_notifier_lock(vm);
 			vma->gpuva.flags &= ~XE_VMA_DESTROYED;
 			xe_svm_notifier_unlock(vm);
 			if (post_commit)
 				xe_vm_insert_vma(vm, vma);
 		}
 		break;
 	}
 	case DRM_GPUVA_OP_REMAP:
 	{
 		struct xe_vma *vma = gpuva_to_vma(op->base.remap.unmap->va);

 		if (op->remap.prev) {
 			prep_vma_destroy(vm, op->remap.prev, prev_post_commit);
 			xe_vma_destroy_unlocked(op->remap.prev);
 		}
 		if (op->remap.next) {
 			prep_vma_destroy(vm, op->remap.next, next_post_commit);
 			xe_vma_destroy_unlocked(op->remap.next);
 		}
 		if (vma) {
 			xe_svm_notifier_lock(vm);
 			vma->gpuva.flags &= ~XE_VMA_DESTROYED;
 			xe_svm_notifier_unlock(vm);
-			if (post_commit)
+			if (post_commit) {
+				/*
+				 * Restore the old va range, in case of the
+				 * prev/next skip optimisation. Otherwise what
+				 * we re-insert here could be smaller than the
+				 * original range.
+				 */
+				op->base.remap.unmap->va->va.addr =
+					op->remap.old_start;
+				op->base.remap.unmap->va->va.range =
+					op->remap.old_range;
 				xe_vm_insert_vma(vm, vma);
+			}
 		}
 		break;
 	}
 	case DRM_GPUVA_OP_PREFETCH:
 		/* Nothing to do */
 		break;
 	default:
 		drm_warn(&vm->xe->drm, "NOT POSSIBLE\n");
 	}
 }



