		case DRM_GPUVA_OP_MAP:
		{
			struct xe_vma *vma;

			vma = new_vma(vm, &op->base.map,
				      op->tile_mask, op->map.read_only,
				      op->map.is_null);
			if (IS_ERR(vma))
				return PTR_ERR(vma);

			op->map.vma = vma;
			break;
		}
		case DRM_GPUVA_OP_REMAP:
